mapper.select:
SELECT ccti.tariff_id, ccti.contract_id, ccti.customs_declaration_method, ( SELECT meaning FROM sys_code_value_b_v WHERE CODE = 'CUSTOMS_DECLARATION_METHOD' AND code_value = ccti.customs_declaration_method ) customs_declaration_method_n, ccti.times, ccti.expense_item, cc.contract_number, bp.bp_name FROM con_contract_tariff_info ccti LEFT JOIN con_contract cc ON cc.contract_id = ccti.contract_id LEFT JOIN prj_project pp ON cc.project_id = pp.project_id LEFT JOIN ( SELECT ppb.project_id, wm_concat( hls.bp_name ) AS bp_name FROM prj_project_bp ppb, hls_bp_master hls WHERE ppb.bp_id = hls.bp_id AND ppb.BP_TYPE IN ( 'TENANT', 'TENANT_SEC', 'ASSET_TRANSFEROR', 'ACCOUNTS_RECEIVABLE' ) GROUP BY ppb.PROJECT_ID ) bp ON pp.PROJECT_ID = bp.project_id
1=1
and ccti.tariff_id = #{tariffId}
and ccti.contract_id = #{contractId}
